function opening(scene,spec,op){const {width:fw,depth}=spec.architecture.footprint,t=spec.architecture.wall_thickness,back=op.wall==='back';const x=back?op.position:-fw/2+t*.62,z=back?-depth/2+t*.62:op.position,ry=back?0:Math.PI/2,inwardX=back?0:.14,inwardZ=back?.14:0,shop=op.treatment.toLowerCase().includes('shop-front'),mapview=op.treatment.toLowerCase().includes('map-window'),campusview=op.treatment.toLowerCase().includes('campus-view');const recess=meshBox(op.width,op.height,.12,shop?'#b9d9d6':mapview?'#91cfe0':campusview?'#8caebb':spec.palette.dark,.04,.55);recess.material.emissive=new THREE.Color(shop?'#7faea8':mapview?'#5f9fb6':campusview?'#566f78':'#283538');recess.material.emissiveIntensity=shop?.24:mapview?.3:campusview?.2:.06;add(scene,recess,[x,op.sill+op.height/2,z],[0,ry,0]);const outer=meshBox(op.width+.48,op.height+.48,.18,spec.palette.trim,.06);const inner=meshBox(op.width,op.height,.2,shop?'#b9d9d6':mapview?'#86c8dc':campusview?'#7899a5':spec.palette.dark,.04);outer.add(inner);inner.position.z=.07;add(scene,outer,[x+inwardX,op.sill+op.height/2,z+inwardZ],[0,ry,0]);const glass=meshBox(op.width-.24,op.height-.24,.04,shop?'#d9eeea':mapview?'#bfe6ee':campusview?'#cde5ea':'#9ccbd4',.025,.28);glass.material.transparent=true;glass.material.opacity=shop?.72:mapview?.76:campusview?.3:.62;add(scene,glass,[x+inwardX*1.9,op.sill+op.height/2,z+inwardZ*1.9],[0,ry,0]);for(const mx of shop?[-op.width*.24,0,op.width*.24]:[0]){const mullion=meshBox(.09,op.height-.2,.12,spec.palette.trim,.02);const mxWorld=back?mx:0,mzWorld=back?0:mx;add(scene,mullion,[x+inwardX*2.2+mxWorld,op.sill+op.height/2,z+inwardZ*2.2+mzWorld],[0,ry,0])}if(shop){const transom=meshBox(op.width-.2,.09,.12,spec.palette.trim,.02);add(scene,transom,[x+inwardX*2.2,op.sill+op.height*.72,z+inwardZ*2.2],[0,ry,0])}if(mapview&&back){const picture=new THREE.Mesh(new THREE.PlaneGeometry(op.width-.34,op.height-.34),new THREE.MeshBasicMaterial({map:illustratedMapTexture(spec),toneMapped:false}));add(scene,picture,[x,op.sill+op.height/2,z+inwardZ*3]);picture.userData.mapGraphic='illustrated street map';const mapMullion=meshBox(.09,op.height-.25,.1,spec.palette.trim,.02);add(scene,mapMullion,[x,op.sill+op.height/2,z+inwardZ*3.18]);const top=meshBox(op.width+.25,.11,.11,spec.palette.trim,.025),bottom=top.clone();add(scene,top,[x,op.sill+op.height-.04,z+inwardZ*3.16]);add(scene,bottom,[x,op.sill+.04,z+inwardZ*3.16]);const title=meshBox(5.4,.68,.2,spec.palette.accent,.07);add(scene,title,[x,op.sill+op.height+.32,z+inwardZ*3.05]);const titleText=textPixels('ADVENTURE MAP',spec.palette.cream,.068,.052);titleText.position.set(0,-.19,.15);title.add(titleText)}if(campusview&&back){const ground=meshBox(op.width-.3,.32,.06,spec.palette.dark,.04);add(scene,ground,[x,op.sill+.25,z+inwardZ*2.7]);for(const [bx,bw,bh,bc] of [[-.34,1.0,1.7,'#d89a55'],[-.12,1.35,2.45,'#77a9ac'],[.13,.9,1.45,'#f1dfb7'],[.32,1.45,2.2,'#5d7d84']]){const b=meshBox(bw,bh,.08,bc,.05);add(scene,b,[x+bx*op.width,op.sill+.42+bh/2,z+inwardZ*2.8]);for(let wy=.42;wy<bh-.2;wy+=.5)for(const wx of [-.22,.22])add(scene,meshBox(.11,.13,.025,spec.palette.cream,.01),[x+bx*op.width+wx*bw,op.sill+.42+wy,z+inwardZ*2.87])}const title=meshBox(4.6,.66,.2,spec.palette.accent,.07);add(scene,title,[x,op.sill+op.height+.3,z+inwardZ*1.8]);const word=textPixels('CAMPUS VIEW',spec.palette.cream,.07,.05);word.position.set(0,-.18,.14);title.add(word)}const sill=meshBox(op.width+.6,.14,.46,spec.palette.trim,.04);add(scene,sill,[x+inwardX*1.2,op.sill-.03,z+inwardZ*1.2],[0,ry,0])}
