function jobWall(scene,spec,open){const p=spec.jobs_wall.position,g=new THREE.Group();const body=meshBox(6.9,1.25,.5,spec.jobs_wall.accent,.12,.65);const face=meshBox(6.35,.88,.18,spec.jobs_wall.face,.09,.82);face.position.z=.32;body.add(face);const letters=textPixels('JOB WALL',spec.jobs_wall.accent,.15,.105);letters.position.set(0,-.31,.49);body.add(letters);g.add(body);const task=meshBox(6.2,2.3,.16,spec.palette.wall_secondary,.08,.9);task.position.set(0,-1.75,.08);g.add(task);for(let i=0;i<5;i++){const c=meshBox(.8,.48,.08,i%2?spec.palette.cream:spec.palette.accent_secondary,.04);c.position.set(-2.35+i*1.16,-.25+(i%2)*.35,.16);task.add(c)}g.position.set(...p);const {width,depth}=spec.architecture.footprint;g.rotation.y=Math.abs(g.position.z)>=depth/2-1?0:(g.position.x<0?Math.PI/2:-Math.PI/2);scene.add(g);const tag=label('JOB WALL','world-action','jobs-wall',open);tag.position.set(0,.98,.35);g.add(tag);g.userData.interactive=open;return g}
function door(scene,spec,open){const g=new THREE.Group(),accent=spec.palette.accent;const frame=meshBox(2.8,4.65,.65,spec.palette.trim,.14);const leaf=meshBox(2.25,4.08,.28,spec.palette.dark,.1,.62);leaf.position.z=.44;frame.add(leaf);const inset=meshBox(1.78,3.55,.08,accent,.07,.58);inset.material.transparent=true;inset.material.opacity=.5;inset.position.z=.63;frame.add(inset);const threshold=meshBox(3.2,.18,1,spec.palette.trim,.05);threshold.position.set(0,-2.26,.1);frame.add(threshold);const sig=textPixels('CAMPUS',spec.palette.cream,.07,.05);sig.position.set(0,1.55,.75);frame.add(sig);g.add(frame);g.position.set(...spec.door.position);const {width,depth}=spec.architecture.footprint;g.rotation.y=Math.abs(g.position.z)>=depth/2-1?0:(g.position.x<0?Math.PI/2:-Math.PI/2);scene.add(g);const tag=label('Campus door','world-action','campus-door',open);tag.position.set(0,2.9,.6);g.add(tag);g.userData.interactive=open;return g}
