  function renderAgent(a,api){const usage=a.token_usage||{};title.textContent=a.display_name||a.handle;body.innerHTML=`<p class="role">${esc(a.role)}${a.team_member?' · project team':' · shared support'}</p><dl class="facts"><dt>Status</dt><dd><span class="status-pill" data-state="${esc(api.state)}">${esc(api.state)}</span></dd><dt>Model</dt><dd>${esc(a.model)}</dd><dt>Activity</dt><dd>${esc(a.usage)}</dd><dt>Token burn</dt><dd>${formatTokens(usage.burn)}</dd><dt>Token usage</dt><dd>${esc(tokenUsageLine(usage))}</dd><dt>Current</dt><dd>${esc(a.current_work||'Not running')}</dd><dt>Last work</dt><dd>${esc(a.last_work)}</dd></dl><p class="live-note">Read-only local Hermes state · refreshes automatically</p>`}
