function bossShell(){document.querySelector('#app').innerHTML=`<section class="campus-shell boss-shell" style="--room-bg:#142224;--accent:#7fd8cf;--cream:#fff4dc"><div id="canvas"></div><div class="hud"><div class="eyebrow">Hermes Agent Campus · operations overview</div><h1>BOSS MODE</h1><p>All rooms, agents, and live operations on one floor. Select a room to enter it.</p></div><div class="controls"><b>Click a room</b> to enter · use its door to return here</div><aside id="panel" class="panel" hidden><header><h2 data-panel-title></h2><button class="close" aria-label="Close">×</button></header><div data-panel-body></div></aside><div class="warp"></div></section>`}

